```kotlin
suspend fun syncNotes() {
    // 1. Push: send local changes since last successful sync
    val localChanges = localDb.getUnsyncedChanges()
    for (change in localChanges) {
        val result = api.pushChange(change, idempotencyKey = change.id)
        if (result.isConflict) {
            resolveConflict(change, result.serverVersion)
        } else {
            localDb.markSynced(change.id)
        }
    }

    // 2. Pull: fetch remote changes since our last-known cursor
    val remoteChanges = api.getChangesSince(localDb.getLastSyncCursor())
    localDb.applyRemoteChanges(remoteChanges)
    localDb.updateSyncCursor(remoteChanges.newCursor)
}
```

Push-then-pull (rather than the reverse) matters here: pushing local changes first means the server has the latest state from this device before this same device pulls — pulling first could mean pulling back a stale version of data this device is about to overwrite anyway, doing redundant work and risking a spurious conflict against changes about to be superseded.
